export function overlapsVehicle(a,position,b){const q=b.renderPosition||b.position;if(!q||a===b)return false;const am=a.model||{},bm=b.model||{};if(position.y+(am.height||1.4)<q.y+.08||q.y+(bm.height||1.4)<position.y+.08)return false;const ay=a.yaw||0,by=b.renderYaw??b.yaw??0,ax={x:Math.cos(ay),z:-Math.sin(ay)},az={x:-Math.sin(ay),z:-Math.cos(ay)},bx={x:Math.cos(by),z:-Math.sin(by)},bz={x:-Math.sin(by),z:-Math.cos(by)},dx=q.x-position.x,dz=q.z-position.z,aw=(am.width||1.8)/2+.04,al=(am.length||4.5)/2+.06,bw=(bm.width||1.8)/2+.04,bl=(bm.length||4.5)/2+.06;
 for(const n of [ax,az,bx,bz]){const ra=aw*Math.abs(n.x*ax.x+n.z*ax.z)+al*Math.abs(n.x*az.x+n.z*az.z),rb=bw*Math.abs(n.x*bx.x+n.z*bx.z)+bl*Math.abs(n.x*bz.x+n.z*bz.z);if(Math.abs(dx*n.x+dz*n.z)>=ra+rb)return false}return true}
